function renderSteps(){
 const r=recording;r.steps??=[];const el=$('#edit-panel');
 el.innerHTML='<div class="section-head"><h2>Smart walkthrough steps</h2><div class="row"><button id="generate-steps">✳ Generate with AI</button><button id="add-step">+ Add step</button></div></div><p class="small">AI drafts use captured screen text and valid timeline moments. Review before saving. Browser narration is a device voice, not an exported AI audio track.</p><div id="step-list"></div><div class="row" style="margin-top:15px"><button id="play-steps">▶ Play narrated steps</button><button id="stop-voice">Stop narration</button></div><p class="note">Zoom is a manual per-step preview setting. Automatic zoom detection, premium AI voices and downloadable narrated video are not yet implemented.</p>';
 const draw=()=>{$('#step-list').innerHTML=r.steps.length?r.steps.map((s,i)=>'<div class="feature step-card"><div class="row"><span class="pill">STEP '+(i+1)+'</span><input data-step-title="'+i+'" value="'+esc(s.title)+'" aria-label="Step '+(i+1)+' title" style="flex:1"><button data-step-jump="'+i+'">'+secondsLabel(s.seconds)+' ↗</button><button data-step-remove="'+i+'" aria-label="Delete step '+(i+1)+'">×</button></div><div class="row" style="margin-top:10px"><label style="margin:0">Time (seconds) <input type="number" min="0" data-step-time="'+i+'" value="'+s.seconds+'" style="width:90px"></label><label style="margin:0">Preview zoom <select data-step-zoom="'+i+'"><option '+(s.zoom===1?'selected':'')+'>1</option><option '+(s.zoom===1.25?'selected':'')+'>1.25</option><option '+(s.zoom===1.5?'selected':'')+'>1.5</option></select>×</label><button data-step-up="'+i+'" '+(i===0?'disabled':'')+'>↑ Move up</button></div><label>Narration / instruction</label><textarea data-step-text="'+i+'" rows="2">'+esc(s.narration)+'</textarea></div>').join(''):'<div class="empty"><p>No steps yet. Add one or ask AI to draft from the captured evidence.</p></div>';
 const each=(sel,fn)=>document.querySelectorAll(sel).forEach(fn);
 each('[data-step-title]',x=>x.onchange=()=>r.steps[+x.dataset.stepTitle].title=x.value);each('[data-step-text]',x=>x.onchange=()=>r.steps[+x.dataset.stepText].narration=x.value);each('[data-step-time]',x=>x.onchange=()=>r.steps[+x.dataset.stepTime].seconds=Math.max(0,Math.min(r.duration,+x.value||0)));each('[data-step-zoom]',x=>x.onchange=()=>r.steps[+x.dataset.stepZoom].zoom=+x.value);
 each('[data-step-remove]',x=>x.onclick=()=>{r.steps.splice(+x.dataset.stepRemove,1);draw()});each('[data-step-up]',x=>x.onclick=()=>{let i=+x.dataset.stepUp;[r.steps[i-1],r.steps[i]]=[r.steps[i],r.steps[i-1]];draw()});each('[data-step-jump]',x=>x.onclick=()=>{const s=r.steps[+x.dataset.stepJump];player?.goto(s.seconds*1000,false);$('#replay').style.transformOrigin='center';$('#replay').style.transform='scale('+s.zoom+')';setTimeout(()=>$('#replay')&&($('#replay').style.transform=''),3500)});
 };draw();
 on('#add-step',()=>{r.steps.push({id:crypto.randomUUID(),seconds:0,title:'New step',narration:'',zoom:1});draw()});
 on('#generate-steps',async()=>{if(r.sample)throw Error('Import or record your own walkthrough before generating AI steps.');const button=$('#generate-steps');button.disabled=true;button.textContent='Generating from evidence...';try{let a=await api('recordings/'+r.id+'/generate-steps',{});if(r.steps.length&&!confirm('Replace current step drafts with the AI draft?'))return;r.steps=a.steps;draw();toast('AI draft generated. Review it and Save edits.')}finally{button.disabled=false;button.textContent='✳ Generate with AI'}});
 on('#play-steps',()=>{if(!('speechSynthesis' in window))throw Error('This browser does not support device narration.');speechSynthesis.cancel();let i=0;const next=()=>{if(i>=r.steps.length)return;let s=r.steps[i++];player?.goto(s.seconds*1000,false);let u=new SpeechSynthesisUtterance(s.narration||s.title);u.onend=next;speechSynthesis.speak(u)};next()});on('#stop-voice',()=>speechSynthesis.cancel());
}
async function renderCollections(){
 const c=await api('collections');if(view!=='collections')return;$('#page').innerHTML='<section class="intro"><div><div class="eyebrow">CURATED WALKTHROUGHS</div><h1>Collections</h1><p class="muted">Group recordings into a focused handover package.</p></div><button id="new-collection" class="primary">+ New collection</button></section><div class="grid" id="collection-grid">'+(c.collections.length?c.collections.map(x=>'<article class="card" data-collection="'+x.id+'"><div class="thumb"><span style="font-size:42px;color:#8d9a7d">▤</span></div><div class="card-body"><h3>'+esc(x.title)+'</h3><p class="small">'+x.recordingIds.length+' recordings · Private collection</p></div></article>').join(''):'<div class="empty"><h2>Create a handover collection</h2><p class="muted">Add related recordings and arrange them for a project.</p></div>')+'</div><p class="note" style="margin-top:25px">Collections are currently private to your workspace. Public collection hubs, collection-level AI and custom branding are still being built.</p>';
 on('#new-collection',async()=>{let m=modal('<h2>New collection</h2><input id="collection-title" placeholder="Collection name" style="width:100%"><button id="create-collection" class="primary" style="margin-top:15px">Create</button>');on('#create-collection',async()=>{if(!$('#collection-title').value.trim())throw Error('Enter a name.');await api('collections',{title:$('#collection-title').value});m.remove();await renderCollections()})});document.querySelectorAll('[data-collection]').forEach(x=>x.onclick=async()=>{try{let a=await api('collections/'+x.dataset.collection);let m=modal('<h2>'+esc(a.title)+'</h2><label>Description</label><textarea id="collection-description" style="width:100%">'+esc(a.description)+'</textarea><h3>Include recordings</h3><div class="node-list">'+library.map(r=>'<label><input type="checkbox" data-include="'+r.id+'" '+(a.recordingIds.includes(r.id)?'checked':'')+'>'+esc(r.title)+'</label>').join('')+'</div><div class="row"><button id="save-collection" class="primary">Save collection</button><button id="delete-collection" class="danger">Delete</button></div>');on('#save-collection',async()=>{await api('collections/'+a.id,{description:$('#collection-description').value,recordingIds:[...document.querySelectorAll('[data-include]:checked')].map(x=>x.dataset.include)},'PATCH');m.remove();await renderCollections()});on('#delete-collection',async()=>{if(!confirm('Delete this collection? Recordings are kept.'))return;await api('collections/'+a.id,null,'DELETE');m.remove();await renderCollections()});}catch(e){toast(e.message)}})
}

function openQuickSearch(){const m=modal('<h2>Quick search</h2><input id="quick-query" aria-label="Quick search recordings" placeholder="Find recordings by name..." style="width:100%"><div id="quick-results"></div>');const draw=()=>{let q=$('#quick-query').value.toLowerCase();$('#quick-results').innerHTML=library.filter(r=>r.title.toLowerCase().includes(q)).slice(0,20).map(r=>'<button class="resource-row" data-quick-id="'+r.id+'">'+esc(r.title)+'</button>').join('')||'<p class="muted">No matching recordings.</p>';document.querySelectorAll('[data-quick-id]').forEach(e=>e.onclick=()=>{m.remove();openRecording(e.dataset.quickId)})};draw();$('#quick-query').oninput=draw;$('#quick-query').focus();}
function openAiDrawer(){if($('#ai-drawer'))return;let drawer=document.createElement('aside');drawer.id='ai-drawer';drawer.className='ai-drawer';drawer.innerHTML='<header><b>✧ Handover AI</b><button id="new-ai-chat">New chat</button><button id="close-ai-drawer" aria-label="Close AI drawer">×</button></header><p class="small">WORKSPACE INTELLIGENCE</p><div id="drawer-chat"><h2>Ask about your recordings</h2><p class="muted">Answers use captured screen text and saved notes, not video pixels. Shared free AI limits apply.</p></div><form id="drawer-form"><textarea id="drawer-question" aria-label="Ask workspace AI" placeholder="Ask anything across your recordings..." required></textarea><button class="primary" id="drawer-send">Send ↑</button></form>';document.body.appendChild(drawer);on('#close-ai-drawer',()=>drawer.remove());on('#new-ai-chat',()=>{$('#drawer-chat').innerHTML='';$('#drawer-question').value=''});$('#drawer-form').onsubmit=async e=>{e.preventDefault();const q=$('#drawer-question').value.trim();if(!q)return;$('#drawer-send').disabled=true;$('#drawer-question').value='';const entry=document.createElement('div');entry.className='chat-answer';entry.textContent='You: '+q+'\n\nSearching captured evidence...';$('#drawer-chat').appendChild(entry);try{const r=await api('ask',{question:q});entry.textContent='You: '+q+'\n\n'+r.answer;for(const m of r.matches||[]){const button=document.createElement('button');button.className='match';button.textContent=m.title+' · '+secondsLabel(m.sec);button.onclick=()=>{drawer.remove();openRecording(m.id)};entry.appendChild(button)}}catch(e){entry.textContent='You: '+q+'\n\n'+e.message}finally{if($('#drawer-send'))$('#drawer-send').disabled=false;entry.scrollIntoView({block:'nearest'})}};$('#drawer-question').focus();}
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'&&document.querySelector('.reference-shell')){e.preventDefault();openQuickSearch()}});
